const b=$json.body??$json,query=String(b.query??'').trim(),sourceUrl=String(b.source_url??'').trim(),products=b.products;
if(!query)return[{json:{ok:false,statusCode:400,error:'query is required'}}];
if(!Array.isArray(products)||products.length<1||products.length>500)return[{json:{ok:false,statusCode:400,error:'products must be an array of 1..500 items'}}];
if(sourceUrl&&!/^https:\/\/(www\.)?torob\.com\//i.test(sourceUrl))return[{json:{ok:false,statusCode:400,error:'source_url must be a valid Torob URL'}}];
const digits=s=>String(s??'').replace(/[۰-۹٠-٩]/g,ch=>{const i='۰۱۲۳۴۵۶۷۸۹'.indexOf(ch);return i>=0?String(i):String('٠١٢٣٤٥٦٧٨٩'.indexOf(ch))});
const numeric=s=>{if(s==null)return null;const raw=digits(s).replace(/\u066B/g,'.').replace(/\u066C/g,',');const match=raw.match(/[0-9][0-9,._\s]*/);if(!match)return null;let n=Number(match[0].replace(/[,._\s]/g,''));if(/میلیون|million/i.test(raw)&&n<1000000)n*=1000000;return Number.isFinite(n)?Math.round(n):null};
const productId=url=>String(url).match(/\/p\/([^/?#]+)/i)?.[1]??'';
const canonical=url=>String(url).split('#')[0].split('?')[0].replace(/\/+$/,'');
const seen=new Set(),rows=[];
for(const p of products){if(!p||typeof p!=='object')continue;const title=String(p.title??p.product_title??'').trim(),url=String(p.url??p.product_url??'').trim();if(!title||!url)continue;const pid=String(p.product_id??'').trim()||productId(url),key=pid?'id:'+pid:'url:'+canonical(url);if(seen.has(key))continue;seen.add(key);const raw=String(p.price??p.price_display??'').trim()||null,stores=String(p.stores??p.store_count_display??'').trim()||null;const ct=(title+' '+String(p.condition??'')+' '+String(p.card_text??'')).toLowerCase(),kt=(title+' '+String(p.product_kind??'')+' '+String(p.card_text??'')).toLowerCase();let condition='نامشخص';if(/کارکرده|استوک|دست.دوم/.test(ct))condition='کارکرده';else if(/آکبند|کالای نو|وضعیت نو/.test(ct))condition='نو';let productKind='نامشخص';if(/طرح|کپی|غیراصل/.test(kt))productKind='طرح';else if(/اصل(ی)?/.test(kt))productKind='اصلی';rows.push({query,product_id:pid||null,product_title:title,price_display:raw,price_toman:numeric(raw),store_count:numeric(stores??p.store_count),condition,product_kind:productKind,is_ad:typeof p.is_ad==='boolean'?p.is_ad:(/تبلیغ|آگهی/.test(String(p.card_text??''))?true:null),product_url:canonical(url),source_url:sourceUrl||null,captured_at:p.captured_at||new Date().toISOString()})}
if(!rows.length)return[{json:{ok:false,statusCode:422,error:'No valid product cards found'}}];
return[{json:{ok:true,count:rows.length,duplicate_count:products.length-rows.length,rows}}];
